import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :forge, ForgeWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# The port, stated here rather than defaulted in runtime.exs. Bandit yields no listener at all
# for a missing `:http` key — not a default — so a release started without PORT would otherwise
# boot healthy, log nothing, and listen on nothing. runtime.exs overrides this when PORT is set.
#
# **Loopback, because `force_ssl` trusts `x-forwarded-proto`.** Anything that can reach this port
# directly can assert that header and the platform will believe it is on TLS: no redirect, and a
# session cookie accepted over cleartext. The header is only trustworthy if the proxy is the only
# thing that can reach the port. `FORGE_HTTP_IP` widens this where a worker has to dial in from
# another machine — see docs/deploy.md, which says what else has to be true then.
config :forge, ForgeWeb.Endpoint, http: [ip: {127, 0, 0, 1}, port: 4000]

# Force using SSL in production. This also sets the "strict-security-transport" header,
# known as HSTS.
#
# **Compile-time, which is why `docs/deploy.md` § Behind a proxy proposes nothing runtime-shaped
# in its place.** Phoenix reads `:force_ssl` with `Application.compile_env/2`, so trusting a
# named proxy instead of the `x-forwarded-proto` header would be a build-time decision, not a
# variable an operator sets — see that section for what that costs a container.
#
# `/health` is excluded because a probe is the one request with no proxy in front of it to put
# the header there: a container runtime asks the container's own address, over cleartext, and
# reads the 301 a redirect would give as unhealthy. Excluding it costs nothing — it carries no
# credential and answers `ok` to anyone (`ForgeWeb.Plugs.Health`). The hosts are the default,
# restated because naming `:exclude` at all replaces it.
config :forge, ForgeWeb.Endpoint,
  force_ssl: [
    rewrite_on: [:x_forwarded_proto],
    exclude: [
      paths: ["/health"],
      hosts: ["localhost", "127.0.0.1"]
    ]
  ]

# Do not print debug messages in production
config :logger, level: :info

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
